import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression

MAX_DRIVERS = 5

def design(feats):
    # Filter out near-duplicates based on correlation
    corr_pairs = []
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids[i+1:], i+1):
            if abs(np.corrcoef(feats.x[:,i], feats.x[:,j])[0,1]) >= 0.6:
                corr_pairs.append((fid1, fid2))

    # Build set of near-duplicates to avoid
    near_dupes = set()
    for a, b in corr_pairs:
        near_dupes.add(a)
        near_dupes.add(b)

    # Score features by effect size and statistical significance
    scores = []
    for i, fid in enumerate(feats.ids):
        if fid in near_dupes:
            continue
        t_stat = np.abs(np.mean(feats.x[feats.y==1,i]) - np.mean(feats.x[feats.y==0,i]))
        p_val = stats.ttest_ind(feats.x[feats.y==1,i], feats.x[feats.y==0,i]).pvalue
        auc = 0.5 + 0.5 * (np.mean(feats.x[feats.y==1,i]) - np.mean(feats.x[feats.y==0,i])) / np.std(feats.x[:,i])
        scores.append((fid, t_stat, p_val, auc))

    # Sort by t-statistic (descending)
    scores.sort(key=lambda x: x[1], reverse=True)

    # Select top candidates
    candidates = [s[0] for s in scores[:20]]

    # Try simple logistic regression with each candidate
    best_drivers = []
    for fid in candidates:
        X = feats.x[:, feats.column(fid)].reshape(-1, 1)
        model = LogisticRegression(penalty='l1', solver='liblinear').fit(X, feats.y)
        if model.coef_[0][0] != 0:
            best_drivers.append(fid)
            if len(best_drivers) >= 4:  # Changed from MAX_DRIVERS to 4
                break

    # If we found drivers, return them with their associated features
    if best_drivers:
        # Include all correlated features to prevent overfitting
        columns = set(best_drivers)
        for a, b in corr_pairs:
            if a in columns or b in columns:
                columns.add(a)
                columns.add(b)
        columns = list(columns)

        # Add interaction terms for strong correlations
        products = []
        for a, b in corr_pairs:
            if a in columns and b in columns:
                products.append((a, b))

        return Design(
            drivers=tuple(best_drivers),
            columns=tuple(columns),
            products=tuple(products),
            loadings={fid: 1.0 for fid in columns}
        )

    # No mechanism found
    return Design(drivers=(), columns=(), products=(), loadings={})

